<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import {useRouter} from 'vue-router'
import {validatePracticeImport,importPracticeDraft} from '@/api/admin-practice'
import {ApiError} from '@/api/client'
import {errorMessage} from '@/api/identity'
import {blankClozeQuestions,blankMatchQuestions,blankMetadata} from '@/practice/admin-draft'
import {getGeneration} from '@/auth/token-session'
import '@/styles/practice.css'
const router=useRouter(),text=ref(''),busy=ref(false),error=ref(''),valid=ref(false),result=ref(''),fields=ref<Record<string,string>>({}),existing=ref('');let epoch=0,requestId=crypto.randomUUID(),candidate:unknown
watch(text,()=>{epoch++;valid.value=false;fields.value={};result.value='内容已变化，请重新校验';existing.value='';requestId=crypto.randomUUID();candidate=undefined})
function example(){text.value=JSON.stringify({articleId:'请替换为已有文章ID',articleVersionId:'请替换为已有版本ID',examCode:'CET4',readingType:'DETAILED',metadata:{title:'Original practice example',titleZh:'原创格式示例',sourceKind:'ORIGINAL',topic:'education',sourceName:'管理员原创',sourceUrl:null,usageNote:'仅为录入格式示例，须使用实际材料并人工校对'},questions:[{key:'q1',type:'DETAIL',stem:'What does the writer suggest?',options:['Keep practising.','Stop learning.','Avoid feedback.','Wait without trying.'],correctOption:'A',explanation:'请根据所选文章填写真实依据；此处仅演示JSON格式。',sortOrder:0}]},null,2)}
function clozeExample(){text.value=JSON.stringify({articleId:'替换为含{{26}}至{{35}}的已有专项材料ID',articleVersionId:'替换为版本ID',examCode:'CET4',readingType:'CLOZE',wordBank:Array(15).fill(''),metadata:{...blankMetadata(),usageNote:'结构模板，非真题；补齐实际材料与来源后校对'},questions:blankClozeQuestions()},null,2)}
function matchExample(){text.value=JSON.stringify({articleId:'替换为含[A]起连续分段标记的已有材料ID',articleVersionId:'替换为版本ID',examCode:'CET4',readingType:'MATCH',wordBank:[],metadata:{...blankMetadata(),usageNote:'仅结构模板，非真题；填写实际材料与来源后校对'},questions:blankMatchQuestions()},null,2)}
async function validate(){busy.value=true;error.value='';valid.value=false;const n=epoch,g=getGeneration();try{if(new TextEncoder().encode(text.value).length>256*1024)throw new Error('单组JSON不能超过256KiB');const raw=JSON.parse(text.value);if(!raw||Array.isArray(raw)||typeof raw!=='object')throw new Error('需要一个单组JSON对象');candidate={...raw,requestId};const r=await validatePracticeImport(candidate);if(n===epoch&&g===getGeneration()){valid.value=r.valid;fields.value=r.fieldErrors;result.value=r.valid?`格式校验通过：${r.itemCount}题。尚未导入或发布。`:'校验未通过，请修改下列问题。'}}catch(e){if(n===epoch)error.value=e instanceof ApiError?errorMessage(e):e instanceof Error?e.message:'JSON格式不正确'}finally{if(n===epoch)busy.value=false}}
async function confirm(){if(!valid.value||!candidate||busy.value)return;const n=epoch,g=getGeneration();busy.value=true;error.value='';try{const r=await importPracticeDraft(candidate);if(n===epoch&&g===getGeneration())await router.push('/admin/practice/'+r.id)}catch(e){if(n===epoch){error.value=errorMessage(e);if(e instanceof ApiError)existing.value=e.fieldErrors?.existingSetId||''}}finally{if(n===epoch)busy.value=false}}
onBeforeUnmount(()=>{epoch++})
</script>
<template><section class="practice-page"><RouterLink to="/admin/practice">← 返回题组列表</RouterLink><header class="practice-heading"><div><h1>JSON导入题组草稿</h1><p>单组JSON最多256KiB、1–10题，引用已有文章版本；导入后仍需逐题校对和发布。</p></div></header><div class="practice-panel"><button :disabled="busy" @click="example">查看原创格式示例</button><button :disabled="busy" @click="clozeExample">查看选词填空结构模板</button><button :disabled="busy" @click="matchExample">查看长篇匹配结构模板</button><p class="practice-hint">示例ID需要替换；不将示例题当作正式校对内容或真题。题目来源和考试时间须有实际依据。</p><label>题组JSON<textarea v-model="text" class="practice-import-text" :disabled="busy" placeholder="粘贴单组题目JSON"/></label><p v-if="error" role="alert" class="practice-notice practice-error">{{error}}</p><p v-if="result" role="status">{{result}}</p><ul v-if="Object.keys(fields).length"><li v-for="(message,path) in fields" :key="path">{{path}}：{{message}}</li></ul><div class="practice-actions"><button :disabled="busy||!text.trim()" @click="validate">校验内容</button><button class="button-primary" :disabled="busy||!valid" @click="confirm">导入为草稿</button><RouterLink v-if="existing" :to="'/admin/practice/'+existing">打开已有题组</RouterLink></div></div></section></template>
